1	// THE UPDATE RUNNER (#768) — the shell that makes the versioned flows actually run
2	// against a member. Everything it decides was decided elsewhere: the flows judge and
3	// write, `terminalFor` says what happens to the PR, `servedBy` says whether this repo
4	// is ours at all. What lives here is the I/O none of them may carry — the clone, the
5	// branch, the commit, the push, the PR, and the hand-off.
6	//
7	// SAME SHAPE AS BASELINING, deliberately. That worker is the proven pattern for
8	// "converge a member from its own Actions run": clone canon fresh, run the CLONE's
9	// scripts as subprocesses rather than the mount's stale copies, deliver on a branch,
10	// and let the shared landing helper own every nuance of arming versus merging. A
11	// second, cleverer shape here would be a second set of the same bugs.
12	//
13	// IT STANDS DOWN unless the repo declares itself served by the update flows. The
14	// inverse of baselining's guard, from the same definition, so exactly one mechanism
15	// converges a mount — and a repo that has said nothing is not this one's to touch.
16	import { execFileSync } from 'node:child_process';
17	import { readFileSync, existsSync, mkdtempSync, writeFileSync, rmSync } from 'node:fs';
18	import { join } from 'node:path';
19	import { tmpdir } from 'node:os';
20	import { pathToFileURL } from 'node:url';
21	import { servedBy, servedByUpdates } from '../../../../engine/served-by.mjs';
22	import {
23	  resolveDelivery, pullCreateError, landDelivery, openDeliveredPull, disposeOpenPull,
24	} from '../../../../engine/scheduler/land-pr.mjs';
25	
26	const CANON_URL = 'https://github.com/missingbulb/Claudinite.git'; // public — no token
27	const UPDATE_PREFIX = 'claudinite/update';
28	const API = 'https://api.github.com';
29	
30	const git = (args, opts = {}) =>
31	  execFileSync('git', args, { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'], ...opts });
32	
33	async function gh(token, path, { method = 'GET', body } = {}) {
34	  const res = await fetch(`${API}${path}`, {
35	    method,
36	    headers: {
37	      authorization: `Bearer ${token}`,
38	      accept: 'application/vnd.github+json',
39	      'x-github-api-version': '2022-11-28',
40	      ...(body ? { 'content-type': 'application/json' } : {}),
41	    },
42	    body: body ? JSON.stringify(body) : undefined,
43	  });
44	  let json = null;
45	  try { json = await res.json(); } catch { /* empty body */ }
46	  return { status: res.status, json };
47	}
48	
49	// --- pure helpers (exported, unit-tested git-free) --------------------------
50	
51	// One branch per run, dated and seeded like baselining's: two runs on one day must
52	// not collide, and a name that carries its date is one a human can read a week later.
53	export const updateBranchName = (day, seed) => `${UPDATE_PREFIX}-${day}-${seed}`;
54	
55	// The line the LIVE CANARY rehearsal greps for. A rehearsal that converges nothing
56	// and exits 0 is worse than no gate at all — it reports a qualification that never
57	// happened — and that is not hypothetical: this exact gate went vacuous the day the
58	// canary flipped to `updates`, because the workflow drove the canary's baselining
59	// worker, which correctly stood down and exited 0 in zero seconds for weeks.
60	//
61	// So the rehearsal announces that it really ran, and the workflow fails when this
62	// line is absent. Any future path that skips the converge is caught by construction
63	// rather than by someone noticing a suspiciously fast green.
64	export const REHEARSAL_MARKER = 'claudinite-rehearsal: converged';
65	
66	// The PR title and body for a terminal. The body is what a human reads when the run
67	// stopped, so it says WHICH terminal fired and why in its first line — a PR that only
68	// says "an update ran" makes every reader re-derive the thing the run already knew.
69	export function updatePullText(terminal, { engine, packs }) {
70	  const moved = [
71	    ...(engine?.from !== engine?.to ? [`engine ${engine?.from ?? 'unstamped'} → ${engine?.to}`] : []),
72	    ...(packs?.plan ?? []).filter((p) => p.from !== p.to).map((p) => `${p.id} ${p.from ?? 'unstamped'} → ${p.to}`),
73	  ];
74	  const title = moved.length ? `Claudinite update: ${moved.join(', ')}` : 'Claudinite update';
75	  const lines = [`**${terminal.action}** — ${terminal.why}`, ''];
76	  if (moved.length) lines.push('Versions moved by this run:', ...moved.map((m) => `- ${m}`), '');
77	  else lines.push('No version moved; this run converged the mount and changed nothing else.', '');
78	  if (terminal.action === 'needs-human') {
79	    lines.push('This PR stays open. Nothing merges on a non-green terminal — see the label.');
80	  } else if (terminal.action === 'apply-stage') {
81	    lines.push('The deterministic half is done. The agent stage applies the new rules to this repo\'s own content before anything merges.');
82	  }
83	  return { title, body: `${lines.join('\n')}\n` };
84	}
85	
86	// --- I/O shell (validated by the live pilot, not unit tests) ----------------
87	
88	export async function main() {
89	  const root = process.env.CLAUDINITE_REPO_ROOT || process.cwd();
90	  const repo = process.env.CLAUDINITE_REPO || process.env.GITHUB_REPOSITORY;
91	  const base = process.env.CLAUDINITE_DEFAULT_BRANCH || 'main';
92	  const token = process.env.GITHUB_TOKEN;
93	  const requestFile = process.env.CLAUDINITE_REQUEST_AGENT;
94	  // REHEARSAL MODE (the live canary): converge this repo against a NAMED canon ref,
95	  // report, and restore the working tree — no branch, no commit, no PR, and above
96	  // all no stamp. A stamped branch head would leave the canary pointing off trunk,
97	  // which is exactly what the next converge's anti-rewind guard refuses: a rehearsal
98	  // that wedges its own canary.
99	  const rehearsalRef = process.env.CLAUDINITE_CANON_REF || null;
100	  if (!repo) { console.error('update: no repo (CLAUDINITE_REPO/GITHUB_REPOSITORY)'); process.exit(1); }
101	  if (!token) { console.error('update: no GITHUB_TOKEN in env'); process.exit(1); }
102	
103	  const checksPath = join(root, '.claudinite-checks.json');
104	  if (!existsSync(checksPath)) { console.log('update: no .claudinite-checks.json — nothing to update'); return; }
105	  const declaration = JSON.parse(readFileSync(checksPath, 'utf8'));
106	
107	  // A repo that declares the RETIRED mechanism is not served by anything: Phase 5
108	  // deleted it. Standing down silently would leave that repo unmaintained with a
109	  // green run to show for it, so the dead end is named and the fix stated.
110	  // Asked as "are these flows mine to run", NOT as a string comparison against one
111	  // spelling. The mechanism was renamed `updates` → `versioned` (#768), and the two
112	  // names are live at once while that record drains — so a literal here would refuse
113	  // a member the moment its own declaration was correctly renamed, which is the
114	  // fielded-worker asymmetry all over again: this file is vendored and a cycle behind
115	  // the flows that rewrite the declaration it reads.
116	  const served = servedBy(declaration);
117	  if (!servedByUpdates(declaration)) {
118	    console.error(`update: this repo declares maintenance.mechanism "${served.mechanism}", which was retired in`
